-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.druid.balance.Name"] = "平衡"
L["rm.era.druid.balance.Description"] = "平衡，適用於 1 至 60 級，也是德魯伊在取得天賦前或沒有其他內建循環適用時的預設循環。學會星火術後以它作為填充（之前為憤怒；自然之賜觸發時先使用星火術），法力高於 30% 時對會存活較久的目標維持月火術與蟲群，三個以上敵人與你交戰時使用颶風，隊伍中使用精靈之火，移動時使用瞬發法術，法力耗盡時近戰。獵豹或熊形態下會改為提供野性戰鬥的建議。提醒：野性印記、單人時的荊棘術、清晰預兆、沒有任何形態時使用梟獸形態、啟動、自然之握。星火術的降級施法、定身與目標選擇由你自行處理。"
L["rm.era.druid.balance.icyveins.Name"] = "平衡（Icy Veins）"
L["rm.era.druid.balance.icyveins.Description"] = "Icy Veins 針對有 16 個減益效果上限之伺服器的團隊清單，作為推薦的平衡內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。只使用星火術，不使用月火術或蟲群，三個以上敵人與你交戰時使用颶風，只在學會星火術之前使用憤怒。提醒與推薦的內建循環相同。"
L["rm.era.druid.feral.Name"] = "野性戰鬥"
L["rm.era.druid.feral.Description"] = "野性戰鬥是你的主要天賦樹時，從 10 級起的獵豹與熊；由你的形態決定使用哪一種。獵豹：潛行起手，維持精靈之火（野性），節能施法用於撕碎，四個連擊點起使用終結技（學會兇猛撕咬之前以及團隊以外的長時間戰鬥時用撕扯，能量低於 63 時用兇猛撕咬），團隊以外使用掃擊，在目標背後使用撕碎，目標正在攻擊你時使用爪擊，能量遠遠不足、激怒 5/5 且法力有餘時變身回能（再次進入獵豹形態）。熊：缺乏怒氣時使用狂怒，除非已有戰士的挫志怒吼，否則對怪群與精英使用挫志咆哮，兩個以上敵人或怒氣有餘時使用揮擊，否則使用精靈之火（野性）。施法者形態：變身。提醒：每次揮擊都使用槌擊、拉怪前的猛虎之怒、手動群體打擊者、啟動、狂暴回復。站位由你自行處理。"
L["rm.era.druid.feral.warcrafttavern.Name"] = "野性戰鬥（Warcraft Tavern，撕扯與撕咬）"
L["rm.era.druid.feral.warcrafttavern.Description"] = "Warcraft Tavern 的變身回能清單，作為推薦的野性戰鬥內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。五個連擊點時只要撕扯不在就施放（包括團隊中），接著能量低於 63 時從四個連擊點起使用兇猛撕咬，在目標背後使用撕碎，能量遠遠不足時變身回能。熊形態與提醒與推薦的內建循環相同。"
L["rm.era.druid.feral.warcrafttavern.casual.Name"] = "野性戰鬥（Warcraft Tavern，不變身回能）"
L["rm.era.druid.feral.warcrafttavern.casual.Description"] = "Warcraft Tavern 不含變身回能的清單，作為推薦的野性戰鬥內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。以撕碎累積到五個連擊點（在目標正面時用爪擊），接著對會存活的目標使用撕扯、猛虎之怒、兇猛撕咬；否則等待能量。熊形態與提醒與推薦的內建循環相同。"
L["rm.era.druid.feral.wowhead.Name"] = "野性戰鬥（Wowhead 團隊熊）"
L["rm.era.druid.feral.wowhead.Description"] = "推薦的野性戰鬥內建循環中的獵豹，搭配 Wowhead 的團隊裝備熊：每次揮擊都使用槌擊（對怪群請自行切換目標使用槌擊），只有在有 60 點多餘怒氣時才使用揮擊，否則使用精靈之火（野性），戰鬥中不使用挫志咆哮也不使用狂怒。這是推薦的野性戰鬥內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.era.druid.restoration.Name"] = "恢復"
L["rm.era.druid.restoration.Description"] = "恢復是你的主要天賦樹時，從 10 級起的治療。治療你目前的友方目標：自然迅捷後使用治療之觸，對帶有你自己的持續治療效果且生命力低於 40% 的目標使用迅癒，持續維持回春術與癒合，有強化癒合時以癒合作為主要治療，生命力低於 45% 或自然之賜觸發時使用最高等級的治療之觸，否則使用等級 4 的治療之觸。目標為敵人時：月火術、蟲群與憤怒。獵豹或熊形態下不提供建議。提醒：野性印記、清晰預兆、自然迅捷、寧靜、啟動、復生、驅除中毒與詛咒。要治療誰由你決定。"
L["rm.era.druid.restoration.warcrafttavern.Name"] = "恢復（Warcraft Tavern）"
L["rm.era.druid.restoration.warcrafttavern.Description"] = "Warcraft Tavern 依傷害程度分級的治療，作為推薦的恢復內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。作用於你的友方目標，傷害不高時不維持持續治療效果：低於 40% 時使用迅癒，低於 50% 時使用等級 5 的癒合，低於 75% 時使用回春術與等級 3 的癒合，自然之賜觸發時使用最高等級的治療之觸，低於 90% 時使用等級 3 的治療之觸。提醒與推薦的內建循環相同。"
L["rm.forever.druid.balance.Name"] = "平衡"
L["rm.forever.druid.balance.Description"] = "平衡，適用於 1 至 60 級，也是沒有其他內建循環適用時所有永久德魯伊的預設循環（1–9 級、未點天賦的施法者、單人的恢復德魯伊）。以憤怒拉怪；移動時刷新月火術、蟲群，隊伍中還有精靈之火。三個以上敵人與你交戰時使用颶風，接著是你自己的月火術與蟲群，蝕星蔽月充能或節能施法期間使用星火術，以及憤怒；無法負擔憤怒時讓你進行近戰。在永久版本中，插件看不到生命力與法力，因此治療自己，以及判斷目標是否值得上持續傷害效果，都由你決定。提醒：野性印記、單人時的荊棘術、梟獸形態、單人時拉怪前的回春術、怪物貼身時的自然之握、單人時戰鬥中只要啟動就緒就使用。形態切換、控場、樹皮術與目標選擇由你自行處理。依據 30 級測試版指南製作；31–60 級的步驟依循職業設計，尚未經過測試。"
L["rm.forever.druid.balance.tavern.Name"] = "平衡，多目標持續傷害（Warcraft Tavern）"
L["rm.forever.druid.balance.tavern.Description"] = "Warcraft Tavern 的多目標持續傷害升級打法，作為推薦的平衡內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。以憤怒拉怪，維持目標身上你自己的月火術與蟲群，兩者都生效且另有敵人與你交戰時以糾纏根鬚定住它，然後是憤怒。不使用星火術（此流派不點蝕星蔽月）。切換到下一個敵人由你決定。提醒：野性印記、單人時的荊棘術。"
L["rm.forever.druid.feral.Name"] = "野性，獵豹與熊"
L["rm.forever.druid.feral.Description"] = "獵豹與熊合併為一個內建循環，依你的形態選擇；一旦野性成為你的主要天賦樹（或已投入 11 點），或你變為獵豹或熊形態，就由它接手。獵豹：潛伏狀態下使用毀滅或撕碎、精靈之火、四個連擊點時使用撕扯、撕扯生效後使用兇猛撕咬、掃擊，然後在目標未面向你時使用撕碎（否則使用爪擊）。熊：遠距離使用精靈之火與野性衝鋒，隊伍中或面對兩個敵人時使用挫志咆哮、原始撕咬，三個以上敵人時使用揮擊、割裂、揮擊。人形態下會建議獵豹形態（學會獵豹前為熊形態）。提醒：熊形態下只要負擔得起就使用槌擊、狂怒、大規模拉怪或面對精英時的狂暴、單人時的啟動、野性印記、荊棘術。在永久版本中，插件看不到生命力、能量、怒氣與法力，因此能量變形、狂暴回復與治療自己都由你決定。嘲諷、中斷施法與站位由你自行處理。"
L["rm.forever.druid.restoration.Name"] = "恢復"
L["rm.forever.druid.restoration.Description"] = "依據 Warcraft Tavern 的隊伍治療，當恢復是你的主要天賦樹且已投入 11 點後生效。治療你目前的友方目標：對帶有你的持續治療效果的目標使用迅癒，野性痊癒，缺少時使用癒合與回春術，治療之觸。在永久版本中，插件看不到生命力與法力，因此你選取的目標是判斷誰需要治療的唯一依據。目標為敵對時：月火術、蟲群、憤怒。提醒：戰鬥中的啟動、戰鬥中對友方目標使用自然迅捷、解除詛咒與驅毒術、野性印記；寧靜由你自行處理。要治療誰與法術等級由你決定；單人的恢復德魯伊使用平衡內建循環。"
L["rm.forever.druid.restoration.icyveins.Name"] = "恢復，持續治療優先（Icy Veins）"
L["rm.forever.druid.restoration.icyveins.Description"] = "Icy Veins 的持續治療優先治療法，作為推薦的恢復內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。對你的友方目標：回春術，缺少時使用癒合，只在兩種持續治療效果都生效時使用治療之觸，對有持續治療效果的目標使用迅癒，然後是野性痊癒（在永久版本中生命力是隱藏的，因此你選取的目標決定誰獲得治療）。啟動冷卻結束即使用。其餘提醒與敵對目標清單與恢復內建循環相同。"
L["rm.mop.druid.balance.Name"] = "推薦"
L["rm.mop.druid.balance.Description"] = "推薦 10 級起的平衡使用，依據 Wowhead 第 5 階段清單與 模擬器。維持月火術與日炎術，並在對應的蝕星蔽月期間刷新它們，月蝕時施放星殞術，流星觸發時及冷卻結束時使用星湧術，五個敵人時在日蝕中使用颶風或在月蝕中使用星界風暴，月蝕期間及之後使用星火術，日蝕期間及之後使用憤怒。Rotation Master 無法讀取蝕星蔽月能量，因此在兩次蝕星蔽月之間，如果星火術是你最近三次施法之一就繼續施放星火術，否則施放憤怒。提醒：野性印記、梟獸形態、蝕星蔽月開始時使用化身、結束時使用星穹大連線（對精英或長時間戰鬥）、自然戒備、自然之力、為塞納留斯之夢使用自然迅捷、啟動、太陽光束、生命力低時使用樹皮術與復原。狂野蘑菇的擺放由你手動處理；引爆提醒預設關閉。你施法、在旅行中、處於獵豹或熊形態，或沒有選取敵人時會停止建議。"
L["rm.mop.druid.feral.Name"] = "推薦"
L["rm.mop.druid.feral.Description"] = "推薦 10 級起的野性戰鬥使用，依據 模擬器 與 Wowhead 第 5 階段清單。讓你進入獵豹形態，從潛行以兇蠻咆哮與劫掠起手，維持兇蠻咆哮，有塞納留斯之夢時在四或五個連擊點利用猛獸迅捷施放治療之觸，五個連擊點時使用撕扯（目標生命力低於 25% 時由兇猛撕咬刷新），撕扯與兇蠻咆哮都還剩六秒時在五個連擊點使用兇猛撕咬，掃擊，節能施法時使用痛擊，目標沒有攻擊你時在節能施法或狂暴期間使用撕碎（Rotation Master 無法判斷你是否在目標背後），以及割碎；四個敵人時使用痛擊與揮擊。熊形態下會提供簡短的坦克清單。提醒：能量低於 35 時使用猛虎之怒、對精英或長時間戰鬥搭配它使用狂暴、化身、自然之力、自然戒備、碎顱猛擊、生命力低時使用求生本能與樹皮術、野性印記。熊形態穿插、憤怒穿插以及野性之心由你手動處理。"
L["rm.mop.druid.feral.icyveins.Name"] = "只在斬殺階段使用撕咬（Icy Veins）"
L["rm.mop.druid.feral.icyveins.Description"] = "Icy Veins 的野性戰鬥順序（Wowhead 的撕咬規則也一致），推薦野性戰鬥內建循環的替代方案：啟用它並停用推薦的循環，或提高它的優先順序。起手、兇蠻咆哮、治療之觸與範圍傷害相同，但目標生命力高於 25% 時，連擊點只用於撕扯與兇蠻咆哮：兇猛撕咬只在斬殺階段刷新撕扯（或在學會撕扯之前消耗五個連擊點）。掃擊在剩下兩秒時刷新，痛擊只在節能施法時使用，狂暴會等到能量 90 且猛虎之怒至少還要 15 秒時才使用。"
L["rm.mop.druid.guardian.Name"] = "推薦"
L["rm.mop.druid.guardian.Description"] = "推薦 10 級起的守護者坦克使用，依據 模擬器 與 Wowhead 第 5 階段清單。讓你進入熊形態，從遠處以精靈之火或以割碎拉怪，以痛擊維持弱化攻擊，對精英以精靈之火維持弱化護甲，受傷時使用塞納留斯之夢的治療之觸，割碎冷卻結束即使用，三個敵人時使用痛擊與揮擊，然後是割裂、痛擊與精靈之火。獵豹形態下（野性之心）會提供簡短的傷害清單。提醒：兇蠻防禦未生效時就使用、狂怒以獲得怒氣、生命力低或怒氣溢出時使用狂暴恢復、怒氣高於 90 或銳齒利爪觸發時使用槌擊、目標攻擊你時使用樹皮術、生命力低時使用求生本能、兩個敵人或首領時使用狂暴與化身、自然之力、自然戒備、塞納里奧結界、碎顱猛擊、野性印記。嘲諷與厄索克之力由你手動處理（兩者的提醒都預設關閉）。"
L["rm.mop.druid.restoration.Name"] = "推薦"
L["rm.mop.druid.restoration.Description"] = "推薦 10 級起的恢復使用，依據 Wowhead 第 5 階段隊伍治療。治療你目前的友方目標，沒有目標時則治療你自己；要治療誰由你決定。對帶有你持續治療效果的目標在其生命力低時、共生消失時，或有森林之魂時為了野性痊癒而使用迅癒；附近有三人受傷時使用野性痊癒；自然迅捷生效時使用瞬發治療之觸；節能施法或目標瀕死時使用癒合；回春術；然後站著不動時使用治療之觸與滋補術。可攻擊的目標會得到月火術與憤怒。提醒：對你的專注目標維持生命之花層數與鐵樹皮術（請將坦克設為專注目標）、隊伍受傷時使用狂野蘑菇:成熟、自然之力、化身、自然戒備、自然迅捷、啟動、自然療癒、塞納里奧結界、樹皮術、野性印記。狂野蘑菇擺放、寧靜與生生不息的提醒預設關閉。"
L["rm.mop.druid.restoration.wowhead.Name"] = "坦克治療（Wowhead）"
L["rm.mop.druid.restoration.wowhead.Description"] = "Wowhead 的單一目標坦克治療順序，在你被指派治療坦克時作為推薦恢復內建循環的替代方案：啟用它並停用推薦的循環，或提高它的優先順序。請保持選取坦克：它會在坦克身上維持三層生命之花與回春術，承受大量傷害時使用癒合，傷害輕微時使用滋補術，生命之花與回春術持續且坦克低於一半時使用治療之觸，並以迅癒讓坦克保持滿血。提醒與推薦的內建循環相同。"
L["rm.mop.druid.unspecialized.Name"] = "選擇專精前"
L["rm.mop.druid.unspecialized.Description"] = "適用於 1 至 9 級，或尚未選擇專精的任何德魯伊；選擇專精後由專精內建循環接手。獵豹形態下維持掃擊，將五個連擊點（對即將死亡的目標為兩個）用於兇猛撕咬，並以割碎累積；熊形態下使用割碎與槌擊。其他情況下以憤怒拉怪，對會存活較久的目標維持月火術，施放憤怒（移動時用月火術），並在你獨自一人且生命力低於一半時建議對自己施放回春術。你施法、在旅行中或沒有選取敵人時會停止建議。"
L["rm.retail.druid.balance.Name"] = "暴雪戰鬥助手"
L["rm.retail.druid.balance.Description"] = "推薦平衡專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的星穹連線（或化身）、對可中斷的施法使用太陽光束、兩波拉怪之間的梟獸形態與野性印記，以及戰鬥中只要就緒就使用樹皮術與你的種族冷卻技能。敵人的施法在戰鬥中會被隱藏，因此太陽光束只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此何時使用樹皮術由你決定。"
L["rm.retail.druid.balance.guide.Name"] = "參考（Icy Veins、SimulationCraft 與 Wowhead）"
L["rm.retail.druid.balance.guide.Description"] = "僅供參考，預設關閉：指南中的平衡優先順序。在至暗之夜的戰鬥中，你的持續傷害效果、蝕星蔽月與觸發效果都對插件隱藏，因此它無法在戰鬥中運作；可以閱讀它，或複製後自行實驗。正式版中星能是隱藏的，因此星湧術只要負擔得起就施放，而不是等到星能溢出前。以梟獸形態與憤怒拉怪。日炎術與月火術消失或即將消失時補上；兩種蝕星蔽月都未生效時觸發蝕星蔽月（三個以上敵人時觸發月蝕，否則觸發日蝕）；織星者的經線、觸及寰宇觸發或面對成群敵人時使用星殞術；織星者的緯線或觸及寰宇觸發時使用星湧術；只要負擔得起就使用星湧術；新月、半月與滿月；蝕星蔽月期間使用狂野蘑菇；月蝕期間或面對成群敵人時使用星火術，否則使用憤怒。提醒：星穹連線或化身、在蝕星蔽月之前使用伊露恩之怒與自然之力、星穹連線期間使用召集魂靈、太陽光束，以及功能性提醒。"
L["rm.retail.druid.feral.Name"] = "暴雪戰鬥助手"
L["rm.retail.druid.feral.Description"] = "推薦野性戰鬥專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的狂暴（或化身）、對可中斷的施法使用碎顱猛擊、戰鬥中只要就緒就使用求生本能、樹皮術與你的種族冷卻技能，以及兩波拉怪之間的獵豹形態與野性印記。敵人的施法在戰鬥中會被隱藏，因此中斷提醒只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此何時使用防禦技能由你決定。"
L["rm.retail.druid.feral.guide.Name"] = "參考（Icy Veins 與 SimulationCraft）"
L["rm.retail.druid.feral.guide.Description"] = "僅供參考，預設關閉：指南中的野性戰鬥優先順序。流血效果與觸發效果在至暗之夜的戰鬥中會被隱藏（連擊點數不會），因此它無法在戰鬥中運作；正式版中能量是隱藏的。以獵豹形態、潛行與掃擊開場。咬嚼；至尊掠食者的渴望觸發時使用兇猛撕咬；五個連擊點數時：兩個以上敵人使用原始憤怒，撕扯消失或只剩最後幾秒時使用撕扯，否則使用兇猛撕咬，寧可等待能量也不要累積超過五點；不足五點時：掃擊消失或即將消失時使用掃擊，月之鼓舞的月火術，三個以上敵人時使用揮擊，撕碎。提醒：戰鬥中只要就緒就使用猛虎之怒、猛虎之怒期間使用狂暴或化身以及野性狂亂或狂上加狂（連擊點數不超過兩點時）、猛虎之怒與狂暴期間且撕扯生效時使用召集魂靈、碎顱猛擊、求生本能，以及功能性提醒。流血效果的快照時機由你自行處理。"
L["rm.retail.druid.guardian.Name"] = "暴雪戰鬥助手"
L["rm.retail.druid.guardian.Description"] = "推薦守護者專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；戰鬥助手只考慮傷害輸出。同時提醒它留給你處理的部分：戰鬥中的狂暴（或化身）與召集魂靈，戰鬥中只要就緒就使用鋼鐵毛皮、狂暴恢復、求生本能、樹皮術與你的種族冷卻技能，對可中斷的施法使用碎顱猛擊，以及兩波拉怪之間的熊形態與野性印記。敵人的施法在戰鬥中會被隱藏，因此碎顱猛擊只會在遊戲顯示它們的場合亮起；正式版中生命力與怒氣是隱藏的，因此何時使用防禦技能由你決定，鋼鐵毛皮也無法等待怒氣達到門檻。"
L["rm.retail.druid.guardian.guide.Name"] = "參考（Icy Veins 與 Wowhead）"
L["rm.retail.druid.guardian.guide.Description"] = "僅供參考，預設關閉：指南中的守護者優先順序。減益效果與觸發效果在至暗之夜的戰鬥中會被隱藏，因此它無法在戰鬥中運作；正式版中怒氣與生命力是隱藏的，因此怒氣達到 80 時的抹除與槌擊傾瀉由你自行處理。痛擊與割碎冷卻結束就使用，單一目標時使用紅月，月火術消失或星河守護者觸發時使用月火術，揮擊。戰鬥中只要就緒就會出現的提醒：鋼鐵毛皮、狂暴恢復、求生本能；兩波拉怪之間的熊形態；狂暴或化身、月之光、召集魂靈、野性之心、碎顱猛擊，以及功能性提醒。"
L["rm.retail.druid.guardian.simc.Name"] = "防禦型參考（SimulationCraft）"
L["rm.retail.druid.guardian.simc.Description"] = "僅供參考，預設關閉：SimulationCraft 的守護者清單，優先把怒氣花在鋼鐵毛皮上。由於戰鬥資料被隱藏，它無法在至暗之夜的戰鬥中運作，而且正式版中怒氣是隱藏的，因此其怒氣門檻未納入。狂暴期間使用鋼鐵毛皮；痛擊消失、即將消失或少於三層時使用痛擊；瀝血毛皮觸發時使用槌擊；三個以上敵人時使用痛擊；紅月造成傷害期間使用割碎；紅月；割碎；痛擊；月火術；揮擊。其中穿插獵豹形態的部分未包含在內。提醒：熊形態、狂暴恢復、求生本能、狂暴或化身、月之光、召集魂靈、碎顱猛擊，以及功能性提醒。"
L["rm.retail.druid.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.druid.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是德魯伊的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個德魯伊內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.retail.druid.restoration.Name"] = "暴雪戰鬥助手，含維持性施法"
L["rm.retail.druid.restoration.Description"] = "推薦恢復專精使用。選取敵人時，它會醒目提示暴雪戰鬥助手的建議，也就是暴雪為恢復專精設計的獵豹形態或人形傷害清單。否則，它會對你的友方目標（或你自己）建議 Icy Veins 的維持性施法：生命之花、戰鬥中使用生命綻放、對回春術使用迅癒、戰鬥中隊伍內使用野性痊癒、節能施法觸發或豐足達到五層時使用癒合、缺少時使用回春術。正式版中生命力與法力是隱藏的，因此這些步驟依你選取的目標進行，而不是依任何人的受傷程度；在至暗之夜的戰鬥中，你的持續治療效果對插件隱藏，因此讀取它們的步驟會在那裡等待。要治療誰以及所有治療冷卻技能都由你決定。提醒：啟動、樹皮術以及你的種族冷卻技能在戰鬥中只要就緒就提醒，兩波拉怪之間提醒野性印記。"
L["rm.sod.druid.balance.Name"] = "平衡（探索賽季）"
L["rm.sod.druid.balance.Description"] = "探索賽季的平衡，適用於 1 至 60 級，也是沒有其他探索賽季內建循環適用時所有德魯伊的預設循環。星湧術的增益效果消失時就使用星湧術，對會存活較久的目標使用日炎術與月火術，只有在星湧術或月蝕強化時才使用星火術，憤怒作為填充，六個以上敵人時使用颶風（紋刻極速強風後為四個），只在移動時使用蟲群。符文會在你紋刻後納入使用。獵豹或熊形態下會提供野性戰鬥的建議。提醒：梟獸形態、星殞術、對瀕死的友方使用瞬發治療之觸、驅除詛咒與中毒、隊伍受傷時使用野性痊癒、啟動。將持續傷害效果擴散到其他目標由你自行處理。"
L["rm.sod.druid.balance.icyveins.Name"] = "平衡（探索賽季，Icy Veins）"
L["rm.sod.druid.balance.icyveins.Description"] = "Icy Veins 的探索賽季清單，作為推薦的探索賽季平衡內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。星湧術冷卻結束即使用，四個以上敵人時使用颶風（為了極速強風），星湧術強化時使用星火術，維持月火術、日炎術與蟲群，憤怒作為填充。提醒與推薦的內建循環相同。"
L["rm.sod.druid.balance.wowhead.Name"] = "平衡（探索賽季，Wowhead）"
L["rm.sod.druid.balance.wowhead.Description"] = "Wowhead 的第 8 階段清單，作為推薦的探索賽季平衡內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。以憤怒開場，星湧術冷卻結束即使用，六個以上敵人時使用颶風，只在移動時使用蟲群，維持日炎術與月火術，紋刻伊露恩之火以延長日炎術時，你的日炎術剩不到 5 秒就使用憤怒，月蝕時使用星火術，否則使用憤怒。提醒與推薦的內建循環相同。"
L["rm.sod.druid.feral.Name"] = "野性戰鬥獵豹（探索賽季）"
L["rm.sod.druid.feral.Description"] = "探索賽季的獵豹，已紋刻兇蠻咆哮時選用（或野性戰鬥是你的主要天賦樹且沒有其他腿部符文時）。沒有精靈之火時使用精靈之火（野性），兇蠻咆哮，四個以上敵人時使用揮擊（獵豹形態），割碎減益效果，節能施法用於撕碎，五個連擊點且兇蠻咆哮剩餘 8 秒時使用撕扯，掃擊，在目標背後使用撕碎或在正面使用割碎，激怒 5/5 時變身回能，最後刷新精靈之火。熊形態下會提供坦克的建議。提醒：能量 60 以下時使用猛虎之怒、搭配猛虎之怒使用狂暴、槌擊、啟動。站位由你自行處理。"
L["rm.sod.druid.restoration.Name"] = "恢復（探索賽季）"
L["rm.sod.druid.restoration.Description"] = "探索賽季的恢復，已紋刻生命之花時選用（或恢復是你的主要天賦樹且沒有其他腿部符文時）。治療你目前的友方目標：自然迅捷或怒風之怒後使用瞬發治療之觸，附近有兩名以上受傷時使用野性痊癒，對帶有你的持續治療效果的目標使用迅癒以觸發生命綻放，或在低於 40% 時使用，三層生命之花在剩下一秒時刷新，回春術，低於 60% 時使用癒合，滋補術，等級 4 的治療之觸。目標為敵人時：日炎術、月火術、憤怒。提醒：危急時刻的生命之樹與求生本能、自然迅捷、寧靜、啟動、復生、復活、驅散。要治療誰由你決定。"
L["rm.sod.druid.tank.Name"] = "熊坦克（探索賽季）"
L["rm.sod.druid.tank.Description"] = "探索賽季的熊坦克，已紋刻割裂時選用。以精靈之火（野性）或日炎術（熊形態）從遠處拉怪，割裂消失前續上，割碎冷卻結束即使用，割裂，揮擊；三個以上敵人時在狂暴期間使用割碎與揮擊。獵豹形態下會執行獵豹清單以作為副坦；施法者形態下會變身為熊形態。提醒：30 點怒氣時使用槌擊、狂暴、求生本能、生命力低時使用狂暴回復與樹皮術、兩波拉怪之間使用狂怒、對精英使用挫志咆哮。嘲諷與目標選擇由你自行處理。"
L["rm.sod.druid.tank.simulator.Name"] = "熊坦克（探索賽季，模擬器 獵豹穿插）"
L["rm.sod.druid.tank.simulator.Description"] = "預設關閉；適合裝備也提供兇蠻咆哮的進階玩家。模擬器 第 7 階段的獵豹穿插：你的掃擊消失時從熊形態切換為獵豹形態，維持兇蠻咆哮與掃擊（以猛虎之怒、割碎累積連擊點），然後回到巨熊形態並執行坦克清單。提醒與推薦的坦克內建循環相同。"
L["rm.tbc.druid.balance.Name"] = "平衡"
L["rm.tbc.druid.balance.Description"] = "施法型平衡，適用於 1 至 70 級，也是沒有其他內建循環適用時所有德魯伊的預設循環。以星火術拉怪（20 級前為憤怒），移動時使用蟲群與月火術，隊伍中使用精靈之火，三個以上敵人時使用颶風，月火術消失且你有 30% 法力時補上月火術，自然之賜觸發時使用星火術，對近戰範圍內的目標使用憤怒，然後是星火術（學會前為憤怒）。獵豹、熊或旅行形態下不提供建議。提醒：野性印記、單人時的荊棘術、清晰預兆、梟獸形態、長時間戰鬥時的自然之力、法力低時的啟動。"
L["rm.tbc.druid.feral.icyveins.Name"] = "野性（Icy Veins、Warcraft Tavern & 模擬器）"
L["rm.tbc.druid.feral.icyveins.Description"] = "野性天賦樹的獵豹與熊，依你目前的形態而定。獵豹：潛行起手（突襲、劫掠或撕碎）、精靈之火(野性)、對會存活的目標在四個連擊點時使用撕扯、兩次撕扯之間沒有節能施法時使用兇猛撕咬、維持割碎、在目標背後使用撕碎，目標正在攻擊你時使用割碎/爪擊。熊：精靈之火、在割裂消失前續上、除非已有戰士的挫志怒吼否則使用挫志咆哮、怪群使用揮擊，接著割碎、疊滿五層割裂、揮擊。人形態下會建議獵豹（或熊）形態。提醒：野性印記、荊棘術、清晰預兆、怒氣有餘時的槌擊、拉怪前的猛虎之怒、狂暴恢復。變身回能（powershifting）是預設關閉的選擇性步驟（需要一個變身回能巨集）。"
L["rm.tbc.druid.feral.wowhead.Name"] = "野性（Wowhead）"
L["rm.tbc.druid.feral.wowhead.Description"] = "Wowhead 的野性，作為推薦的 Icy Veins 野性內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。撕扯不在時於四個連擊點補上，兇猛撕咬只用於即將死亡的目標（不穿插撕咬）；熊形態把空閒的共用冷卻用在割裂上，再使用揮擊。獵豹法力不足時使用啟動。其餘與 Icy Veins 版本相同。"
L["rm.tbc.druid.restoration.Name"] = "恢復"
L["rm.tbc.druid.restoration.Description"] = "恢復天賦樹的治療，作用於你的友方目標（或你自己）：自然迅捷後使用治療之觸，對帶有你的回春術或癒合的瀕死目標使用迅癒，戰鬥中維持三層生命之花持續滾動，缺少時補上回春術與癒合，接著在生命之樹形態下使用癒合，不在該形態時使用治療之觸。目標為敵對時以月火術與憤怒單人練功。提醒：野性印記、清晰預兆、生命之樹、自然迅捷、寧靜、啟動與復生。要治療誰以及降級施法由你自行處理。"
